class Solution {
public:
    vector<long long> countKConstraintSubstrings(string s, int k, vector<vector<int>>& queries) {
        int n = s.size();
        vector<int> left_bound(n, 0);
        int l = 0, z = 0, o = 0;
        for (int r = 0; r < n; ++r) {
            if (s[r] == '0') z++;
            else o++;
            while (z > k && o > k) {
                if (s[l] == '0') z--;
                else o--;
                l++;
            }
            left_bound[r] = l;
        }
        vector<long long> pref(n + 1, 0);
        for (int r = 0; r < n; ++r) {
            pref[r + 1] = pref[r] + (r - left_bound[r] + 1);
        }
        vector<long long> ans;
        for (const auto& q : queries) {
            int ql = q[0], qr = q[1];
            int idx = lower_bound(left_bound.begin() + ql, left_bound.begin() + qr + 1, ql) - left_bound.begin();
            long long cnt1 = idx - ql;
            long long res1 = cnt1 * (cnt1 + 1) / 2;
            long long res2 = pref[qr + 1] - pref[idx];
            ans.push_back(res1 + res2);
        }
        return ans;
    }
};

class Solution {
    public long[] countKConstraintSubstrings(String s, int k, int[][] queries) {
        int n = s.length();
        int[] leftBound = new int[n];
        int l = 0, z = 0, o = 0;
        for (int r = 0; r < n; ++r) {
            if (s.charAt(r) == '0') z++;
            else o++;
            while (z > k && o > k) {
                if (s.charAt(l) == '0') z--;
                else o--;
                l++;
            }
            leftBound[r] = l;
        }
        long[] pref = new long[n + 1];
        for (int r = 0; r < n; ++r) {
            pref[r + 1] = pref[r] + (r - leftBound[r] + 1);
        }
        long[] ans = new long[queries.length];
        for (int i = 0; i < queries.length; ++i) {
            int ql = queries[i][0], qr = queries[i][1];
            int low = ql, high = qr + 1;
            while (low < high) {
                int mid = (low + high) / 2;
                if (leftBound[mid] >= ql) high = mid;
                else low = mid + 1;
            }
            int idx = low;
            long cnt1 = idx - ql;
            long res1 = cnt1 * (cnt1 + 1) / 2;
            long res2 = pref[qr + 1] - pref[idx];
            ans[i] = res1 + res2;
        }
        return ans;
    }
}

var countKConstraintSubstrings = function(s, k, queries) {
    const n = s.length;
    const leftBound = new Array(n);
    let l = 0, z = 0, o = 0;
    for (let r = 0; r < n; r++) {
