        else o++;
        while (z > k && o > k) {
            if (s[l] === '0') z--;
            else o--;
            l++;
        }
        leftBound[r] = l;
    }
    const pref = new Array(n + 1).fill(0n);
    for (let r = 0; r < n; r++) {
        pref[r + 1] = pref[r] + BigInt(r - leftBound[r] + 1);
    }
    const ans = [];
    for (const [ql, qr] of queries) {
        let low = ql, high = qr + 1;
        while (low < high) {
            const mid = Math.floor((low + high) / 2);
            if (leftBound[mid] >= ql) high = mid;
            else low = mid + 1;
        }
        const idx = low;
        const cnt1 = BigInt(idx - ql);
        const res1 = cnt1 * (cnt1 + 1n) / 2n;
        const res2 = pref[qr + 1] - pref[idx];
        ans.push(Number(res1 + res2));
    }
